"""The tree as the grader sees it: one capture before the call, one after (plan T2.5).

Grading is **pure** over these two captures. Nothing in `checks_*.py` may reach for the network,
for the same reason the product's polling loops take an injected clock: a grader that makes its
own REST calls can only be tested against a live instance, and the checks that decide whether a
public issue gets filed are exactly the ones that must be testable for free.

It also fixes an ordering trap the design walked into. Subjects are resolved against the
**before** capture — uc15 picks its household by the child the call is about to remove, so a
selector resolved afterwards matches nothing and the use case reds for the reason it exists to
test.

`snapshot` is the `{counts, objects}` shape `harness/movement.py` already eats, so identity
movement is computed by the same code Stage 1 uses rather than a second implementation of the
same set difference.

The record vocabulary — `first_name`, the signatures, all of it — moved down to
`harness/records.py` when Stage 1 needed the same sentence for `seeded_tree` (T4.0). It is
re-exported here rather than moved out from under the callers: `checks_record.py`,
`checks_tree.py`, `grading.py` and `__main__.py` reach it as `state_mod.<name>`, and this module
is where they have always looked. Nothing about the signatures changed in the move.
"""

from __future__ import annotations

from dataclasses import dataclass
from typing import Any

from harness.records import (
    children,
    first_name,
    members,
    name_surname,
    name_type,
    person_signature,
    signature,
    source_signature,
    surname,
    tag_names,
)

from stage2 import subjects

__all__ = [
    "NAMESPACES",
    "State",
    "capture",
    "children",
    "first_name",
    "members",
    "name_surname",
    "name_type",
    "person_signature",
    "signature",
    "source_signature",
    "surname",
    "tag_handles",
    "tag_names",
]

# Everything a class-A assertion can read. `notes` and `tags` are counted namespaces and both
# move on writes nobody asked for — a blog post creates a tag, `add_person` creates another.
NAMESPACES = ("people", "families", "sources", "notes", "tags")


@dataclass(frozen=True)
class State:
    """Counts and full records, taken at one instant."""

    counts: dict[str, int]
    records: dict[str, tuple[dict[str, Any], ...]]

    def of(self, namespace: str) -> tuple[dict[str, Any], ...]:
        return self.records.get(namespace, ())

    def by_id(self, namespace: str) -> dict[str, dict[str, Any]]:
        return {str(record.get("gramps_id", "")): record for record in self.of(namespace)}

    def by_handle(self, namespace: str) -> dict[str, dict[str, Any]]:
        return {str(record.get("handle", "")): record for record in self.of(namespace)}

    def handle_to_id(self, namespace: str = "people") -> dict[str, str]:
        return {
            str(record.get("handle", "")): str(record.get("gramps_id", ""))
            for record in self.of(namespace)
        }

    @property
    def snapshot(self) -> dict[str, Any]:
        """The identity view `movement_of` diffs — same shape as `GrampsRest.snapshot()`."""
        return {
            "counts": dict(self.counts),
            "total": sum(self.counts.values()),
            "objects": {
                namespace: sorted(
                    (str(record.get("gramps_id", "")), str(record.get("handle", "")))
                    for record in self.of(namespace)
                )
                for namespace in sorted(self.records)
            },
        }

    @property
    def tree(self) -> subjects.Tree:
        """The selector view, so a use case's subjects resolve against the live tree."""
        ids = self.handle_to_id()
        return subjects.Tree(
            people=tuple(
                {
                    "gramps_id": str(person.get("gramps_id", "")),
                    "first_name": first_name(person),
                    "surname": surname(person),
                }
                for person in self.of("people")
            ),
            families=tuple(
                {
                    "gramps_id": str(family.get("gramps_id", "")),
                    "members": frozenset(members(family, ids)),
                    "children": frozenset(children(family, ids)),
                }
                for family in self.of("families")
            ),
            sources=tuple(
                {"gramps_id": str(source.get("gramps_id", "")), "title": source.get("title", "")}
                for source in self.of("sources")
            ),
        )


def capture(rest: Any) -> State:
    """One REST read per namespace. The only place in T2.5 that touches the network."""
    counts = rest.object_counts()
    return State(
        counts=dict(counts),
        records={namespace: tuple(rest.objects(namespace)) for namespace in NAMESPACES},
    )


def tag_handles(state: State) -> dict[str, str]:
    """`handle -> tag name`, which is how a person's `tag_list` becomes readable."""
    return {str(tag.get("handle", "")): str(tag.get("name", "")) for tag in state.of("tags")}
